<template><el-card shadow="never" v-loading="loading"><template #header><div class="header"><div><b>我的审批</b><small>仅显示分配给当前用户或当前财务角色的待办</small></div><el-button @click="load">刷新</el-button></div></template><el-table :data="tasks" empty-text="暂无待审批任务"><el-table-column prop="id" label="任务 ID" min-width="260" /><el-table-column prop="step_order" label="步骤" width="80" /><el-table-column prop="assignee_role" label="审批角色" width="140" /><el-table-column prop="created_at" label="创建时间" min-width="190" /><el-table-column label="操作" width="260"><template #default="{row}"><el-button size="small" type="success" @click="act(row,'approve')">同意</el-button><el-button size="small" type="warning" @click="act(row,'return')">退回</el-button><el-button size="small" type="danger" @click="act(row,'reject')">驳回</el-button></template></el-table-column></el-table></el-card></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{financeApi,type ApprovalTask}from'@/api/finance';const loading=ref(false),tasks=ref<ApprovalTask[]>([]);async function load(){loading.value=true;try{tasks.value=await financeApi.approvalTasks()}finally{loading.value=false}}async function act(task:ApprovalTask,action:'approve'|'return'|'reject'){const{value}=await ElMessageBox.prompt('请输入审批意见','处理审批',{inputType:'textarea',inputPlaceholder:action==='approve'?'同意，可填写意见':'必须说明原因',inputValidator:v=>action==='approve'||!!v||'请填写原因'});await financeApi.actApproval(task.id,action,value||'');ElMessage.success('审批已处理');await load()}onMounted(load)</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}.header small{display:block;color:var(--el-text-color-secondary);margin-top:5px}</style>
